type CardType = {
    Employer:string[],
    Job: string,
    img: string,
    work: string,
    link: string,
}

const Card = ({ Employer, Job, img, work, link }: CardType) => {
    const [hover, setHover] = useState(false);
    return (
        <div
            className={`${styles.cardBlur} ${styles.darkMorphic}`}
            style={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent:"center",
                borderRadius:"20px", 
                margin: "1%" ,
                textAlign: "center",
                width: "27%",
                height: "70vh",
                paddingInline: 25,
            }}
            onMouseEnter={()=> {setHover(true)}}
            onMouseLeave={()=>setHover(false)}
        > 
            <img src={img} height="100vw" style={{borderRadius: 10, marginBottom: 10}}/>
            <h3>{Employer[0]}</h3>
            {Employer.length > 1 && <h4 style={{fontStyle:"italic"}}>{Employer[1]}</h4>}
            <p style={{ marginBottom: 10}}>{Job}</p>
            <p style={{color: "lightgray"}}>{work}</p>

            <a 
                href={link} 
                style={{marginTop: 20, fontWeight: "bold"}}
            >
                <LearnMore/>
            </a> 
        </div>
    )
}
