import React, { useState, useEffect } from 'react'
import styles from "./page.module.css";

import { Menu } from './components/headerBar';
import Landing from './pages/landing';
import Skills from './pages/skills';
import Experience from './pages/experience';
import Projects from './pages/projects';
import Business from './pages/business';
import About from './pages/about';
import Education from './pages/education';

import home from './assets/Home-icon.svg'
import educationIcon from "./assets/education.svg"
import workIcon from "./assets/work.svg"
import startupIcon from "./assets/startup.svg"
import globalIcon from "./assets/global.png"
// import projectIcon from " ./assets/project.svg"

export default function Home() {
  const [selected, setSelected] = useState("About");
  const [sections, setSections] = useState<NodeListOf<HTMLElement>>();

  const Pages = [
    {
      name: "Home",
      icon: home,
      comp: Landing,
    },
    {
      name: "Entrepreneurship",
      icon: globalIcon,
      comp: Business,
    },
    {
      name: "Employment",
      icon: workIcon,
      comp: Experience,
    },
    // {
    //   name: "About Me",
    //   icon: home,
    //   comp: About,
    // },
    // {
    //   name: "Projects",
    //   icon: home,
    //   comp: Projects,
    // },
    {
      name: "Education",
      icon: educationIcon,
      comp: Education,
    },
  ];
  

  function scrollToSection(sectionId: string) {
    const targetSection = document.getElementById(sectionId);

    if (targetSection) {
      const targetOffset = targetSection.offsetTop;

      const scrollOptions : ScrollToOptions  = {
        top: targetOffset,
        behavior: 'smooth'
      };
      window.scrollTo(scrollOptions);
    }
    
    setSelected(sectionId)
  }

  function onScroll() {
    const currentPosition = window.scrollY; 

    if (sections) {
      sections.forEach((section: HTMLElement) => {
        const sectionTop = section.offsetTop;
        const sectionBottom = sectionTop + section.offsetHeight - 60;
        
        console.log(sectionTop + " : " + currentPosition + " : " +sectionBottom)


        if (currentPosition >= sectionTop - 300 && currentPosition <= sectionBottom) {
          const sectionId = section.getAttribute('id');
          if (sectionId) {
            setSelected(sectionId)
          }
        }
      })
    }
  }

  window.addEventListener('scroll', () => {
    onScroll();
  });

  useEffect(() => {
    setSections(document.querySelectorAll('section'));
  },[])

  return (
    <main 
      className={`${styles.main}`}
      style={{
        backgroundColor: "var(--white)"
      }}
    
    >
      <Menu 
        items={Pages} 
        onClick={(event) => 
            scrollToSection(event)
        }
        selected={selected}
      />
      
      <div className={styles.center}>
        {
          Pages.map((c, index)=> (
            <section 
                key={c.name+index} 
                id={c.name} 
                className={`${styles.section}`}
            >
              <c.comp/>
            </section>
          ))
        }
      </div>
    </main>    
  );
}
