import React, { useState } from 'react'
import { MenuComponent } from "./types"
import styles from "../../page.module.css"

export const Menu: MenuComponent = ({items, onClick, selected}) => {
    const [hover, setHover] =  useState<string>("");

    return (
        <>
            <div 
                id="headerBar"
                className={`${styles.cardBlur} ${styles.darkMorphic} ${styles.menuBar}
                `} 
            >
                <div style={{display: "flex", flexDirection: "column", flex: 2}}>
                    {items.map((i) => (
                        <div 
                            id={i + "_heading"} 
                            key={i + "_heading_id"}
                            onClick={() => onClick(i.name)} 
                            onMouseEnter={() => setHover(i.name)}
                            onMouseLeave={() => setHover("")}
                            style={{
                                display: "flex",
                                cursor: "pointer",
                                marginBottom: "70%",
                            }}
                        > 
                            <img
                                src={i.icon}
                                width={"30vw"}
                                alt="LinkedIn Icon"
                                style={{
                                    filter:  "invert(100%)",
                                    opacity: i.name === selected ? 0.9 : 0.3,
                                }}
                            />
                            {
                                i.name === hover && 
                                <div
                                    className={
                                        `${styles.darkMorphic} ${styles.menuBubble}`
                                        
                                    }
                                    style={{
                                        position: "absolute", // Positions it relative to the parent div
                                        left: "4.3vw", // Adjust this to control the horizontal distance from the image
                                        marginTop: "0.5vh",
                                        backgroundColor: "rgba(0,0,0,0.8)",
                                        color: "white"
                                    }}
                                >
                                    <p>{i.name}</p>
                                </div>
                            }
                        </div>
                    ))}

                </div>
                

                <div style={{display: "flex", flexDirection: "column", justifyContent:"flex-end", flex: 1, textAlign: "center"}}>
                    <code style={{fontSize: "4%"}}>Built by</code>
                    <h3>LK</h3>
                </div>
                
            </div>
        </>
    );
}