type CardType = {
    Employer:string[],
    Job: string,
    img: string,
    work: string,
    link: string,
}

const Card = ({ Employer, Job, img, work, link }: CardType) => {
    const [hover, setHover] = useState(false);
    return (
        <div
            className={`${styles.cardBlur} ${styles.morphic}`}
            style={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent:"center",
                borderRadius:"20px", 
                textAlign: "center",
                maxHeight: "30vh",
                maxWidth: "60%",
                paddingInline: "7%",
                paddingBlock: "7%",
                color: "gray"
            }}
            onMouseEnter={()=> {setHover(true)}}
            onMouseLeave={()=>setHover(false)}
        > 
            <img src={img} height="80vw" style={{borderRadius: 10, marginBottom: 10}}/>
            <h3 style={{fontSize: 20}}>{Employer[0]}</h3>
            {Employer.length > 1 && <h4 style={{fontStyle:"italic"}}>{Employer[1]}</h4>}
            <p style={{ marginBottom: 10}}>{Job}</p>
            {/* <p>{work}</p>   */}
        </div>
    )
}

const Slides = () => {
    const wabf: string[] = [ wabf1, wabf2, wabf3, wabf4, wabf5, wabf6, wabf7, wabf8, wabf9]

    return (
        <Swiper
            pagination={{
                dynamicBullets: true,
            }}
            modules={[Pagination, Autoplay]}
            loop={true}
            className="mySwiper"
            autoplay={{
                delay: 4000,
                disableOnInteraction: false,
                pauseOnMouseEnter: true,
            }}
            style={{
                maxWidth: "50%", // Make Swiper take full width
                maxHeight: "60vh", // Set desired height
            }}
        >
            {
                wabf.map((w, index)=> (
                    <SwiperSlide 
                        key={"wabf" + index}
                        style={{
                            display: "flex", 
                            justifyContent: "center"
                        }}
                    >
                        <img 
                            src={w} 
                            alt={`wabf-slide-${index}`}
                            style={{
                                borderRadius: 20,
                                maxWidth: "100%",
                                maxHeight: "60vh",
                                objectFit: "contain",
                            }}
                        />                        
                    </SwiperSlide>
                ))
            }
        </Swiper>
      );
}

